<?php

/**
 * Proves that the documented installation path actually works: credentials
 * generated by the shipped helper must authenticate against the server.
 */

declare(strict_types=1);

return function (Suite $suite): void {
    $suite->test('generated credentials authenticate against a fresh install', function () {
        $script = Harness::projectRoot() . '/deploy/gen-credentials.php';
        Assert::true(is_file($script), 'the credential generator must ship with the project');

        $descriptors = [1 => ['pipe', 'w'], 2 => ['pipe', 'w']];
        $process = proc_open(
            [Harness::php(), '-n', $script, '3', '--json'],
            $descriptors,
            $pipes
        );
        Assert::true(is_resource($process), 'the generator must be runnable');

        $output = (string) stream_get_contents($pipes[1]);
        $errors = (string) stream_get_contents($pipes[2]);
        fclose($pipes[1]);
        fclose($pipes[2]);
        proc_close($process);

        Assert::same('', trim($errors), 'the generator must not emit diagnostics');

        $credentials = json_decode($output, true);
        Assert::true(is_array($credentials), 'the JSON output must decode');
        Assert::greaterOrEqual(32, strlen($credentials['serverSecret']), 'the secret must satisfy the minimum');
        Assert::count(3, $credentials['accessTokens'], 'three clients were requested');

        foreach ($credentials['accessTokens'] as $ip => $token) {
            Assert::true(
                preg_match('/^10\.99\.99\.(?:[2-9]|[1-9]\d|1\d\d|2[0-4]\d|25[0-4])$/', (string) $ip) === 1,
                'address ' . $ip . ' must be inside the client range'
            );
            Assert::true(
                preg_match('/^[0-9a-f]{64}$/', (string) $token) === 1,
                'the token for ' . $ip . ' must be 64 lowercase hex characters'
            );
        }
        Assert::count(
            3,
            array_unique($credentials['accessTokens']),
            'no two clients may share a token'
        );

        $literal = "[\n";
        foreach ($credentials['accessTokens'] as $ip => $token) {
            $literal .= '    ' . var_export($ip, true) . ' => ' . var_export($token, true) . ",\n";
        }
        $literal .= ']';

        $instance = Harness::instance([
            'SERVER_SECRET' => var_export($credentials['serverSecret'], true),
            'ACCESS_TOKENS' => $literal,
        ]);

        $addresses = array_keys($credentials['accessTokens']);
        $sender = $addresses[0];
        $recipient = $addresses[1];

        $uuid = SignRequest::uuid();
        $body = SignRequest::body(
            $sender,
            $credentials['accessTokens'][$sender],
            $credentials['serverSecret'],
            'sync',
            [SignRequest::packet($sender, $recipient, 'generated credentials work', $uuid)]
        );
        $result = Vpn::resultOf(Vpn::post($instance, $body), 'send with generated credentials');
        Assert::same([$uuid], $result['acceptedPacketUuids'], 'the packet is stored');

        $received = SignRequest::body(
            $recipient,
            $credentials['accessTokens'][$recipient],
            $credentials['serverSecret'],
            'sync'
        );
        $deliveries = SignRequest::deliveries(Vpn::post($instance, $received)['body']);
        Assert::count(1, $deliveries, 'and delivered to the recipient');
        Assert::same($uuid, $deliveries[0]['packet']['uuid'], 'intact');
    });

    $suite->test('the shipped webserver rules cover every queue artefact', function () {
        $apache = (string) file_get_contents(Harness::projectRoot() . '/deploy/apache.htaccess');
        $nginx = (string) file_get_contents(Harness::projectRoot() . '/deploy/nginx.conf');

        foreach (['data', 'sending', 'writing', 'error', 'stat', 'lock', 'bin', 'log'] as $extension) {
            Assert::contains($extension, $apache, 'the Apache rules must cover .' . $extension);
            Assert::contains($extension, $nginx, 'the nginx rules must cover .' . $extension);
        }
        Assert::contains('X_FORWARDED_PROTO', $nginx, 'nginx must forward the scheme for the HTTPS check');
        Assert::contains('client_max_body_size', $nginx, 'nginx must allow a full sync body');
    });
};
